insert into saved values('full',pg_temp.book()),('register',public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":false}'));
insert into tap_results select is((select data-array['invoices','entries','next','asOf'] from saved where name='register'),(select data-array['invoices','entries','next','asOf'] from saved where name='full'),'Register preserves every exact account, total, classification and warning');
insert into tap_results select is((select jsonb_array_length(data->'invoices') from saved where name='register'),0,'Register does not send invoice history');
insert into tap_results select is((select jsonb_array_length(data->'entries') from saved where name='register'),0,'Register does not send payment history');
insert into tap_results select is((select data->>'next' from saved where name='register'),null,'Register has no invoice cursor');
insert into tap_results select is((select jsonb_array_length(data->'invoices') from saved where name='full'),50,'Legacy callers retain the original invoice page');
insert into tap_results select is((select data->>'next' from saved where name='full'),'50','Legacy callers retain the next invoice cursor');
insert into tap_results select ok((select octet_length(data::text) from saved where name='register')<(select octet_length(data::text)/2 from saved where name='full'),'Register omits heavy source and invoice details');
insert into tap_results select is((select data#>>'{exactTotals,outstanding}' from saved where name='register'),'9007199254826891','Large totals retain exact centavos');
insert into tap_results select is(public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":true}')-array['asOf'],pg_temp.book()-array['asOf'],'Explicit history mode matches legacy history');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":"false"}')$$,'P0001','Choose a valid credit history view','Invalid view flag rejected');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":false,"offset":50}')$$,'P0001','The account register does not have invoice pages','Register cannot request an invoice page');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx()||jsonb_build_object('includeHistory',false,'clientId',pg_temp.i(801)))$$,'P0001','The account register does not have invoice pages','Account detail always uses history mode');
insert into tap_results select lives_ok($$select public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":false}')$$,'Authorized cashier can read the register');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":false}')$$,'42501','Only authorized sales staff can access client credit','Stock-only staff cannot use the new view');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx()||'{"includeHistory":false}')$$,'42501','Only authorized sales staff can access client credit','Other business cannot use the new view');
insert into tap_results select ok(not has_function_privilege('authenticated','app_private.credit_book_snapshot(uuid,uuid,uuid,integer,boolean)','EXECUTE'),'No direct authenticated execution of private snapshot');
insert into tap_results select ok(not has_function_privilege('anon','app_private.credit_book_snapshot(uuid,uuid,uuid,integer,boolean)','EXECUTE'),'No anonymous execution of private snapshot');
insert into tap_results select is((select count(*)::int from public.sales),1,'Read modes create no sales');
insert into tap_results select is((select count(*)::int from public.credit_invoices),61,'Read modes preserve all invoices');
